window.SCHOOL_LISTENING={"../assets/media/78b080912c38e386bf3d14e6a3ae54a345fcf5adec1b9d98d81219c2703652e5.mp3":[{"id":"PPT_78b080912c38e386","audioId":"PPT_78b080912c38e386","title":"Book 3 · Unit 1 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 95","duration":36.41,"cues":[{"start":0,"end":2.26,"text":"one .six","coverage":1},{"start":2.26,"end":3.14,"text":"one","coverage":1},{"start":3.98,"end":4.68,"text":"Large,","coverage":1},{"start":5.52,"end":6.08,"text":"white,","coverage":1},{"start":7.08,"end":7.44,"text":"strong","coverage":1},{"start":8.98,"end":10.38,"text":"two","coverage":1},{"start":11,"end":12.12,"text":"Pandas,","coverage":1},{"start":12.78,"end":13.76,"text":"sea turtles,","coverage":1},{"start":14.52,"end":15.54,"text":"chimpanzees,","coverage":1},{"start":16.28,"end":16.86,"text":"tigers","coverage":1},{"start":18.7,"end":20.1,"text":"three","coverage":1},{"start":21,"end":21.76,"text":"Poachers,","coverage":1},{"start":22.34,"end":23.3,"text":"loss of habitat,","coverage":1},{"start":24.74,"end":25.74,"text":"human contact","coverage":1},{"start":27,"end":30.18,"text":"four More guards,","coverage":1},{"start":30.9,"end":32.48,"text":"a ban on selling ivory,","coverage":1},{"start":33.6,"end":34.26,"text":"building fences","coverage":1}],"file":"3635ef9f464e8b99763c.js","track":0,"media":"../assets/media/78b080912c38e386bf3d14e6a3ae54a345fcf5adec1b9d98d81219c2703652e5.mp3"}],"../assets/media/5bf8f7a4809ea3e1fe318be3a7371f0006a4963ec39b28d06cc8481413f0e55c.mp3":[{"id":"PPT_5bf8f7a4809ea3e1","audioId":"PPT_5bf8f7a4809ea3e1","title":"Book 3 · Unit 1 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 92","duration":43.18,"cues":[{"start":0,"end":1.94,"text":"one .three","coverage":1},{"start":1.94,"end":3.06,"text":"one","coverage":1},{"start":4.08,"end":13.56,"text":"First, there needs to be an increase in the number of specially trained guards who work in the rainforests to catch the poachers.","coverage":1},{"start":15.5,"end":17.44,"text":"two two.","coverage":1},{"start":18.14,"end":25.56,"text":"Governments must introduce an immediate and complete ban on anyone buying or selling ivory,","coverage":1},{"start":26.14,"end":28.5,"text":"even between countries sharing a border.","coverage":1},{"start":30.82,"end":31.7,"text":"three","coverage":1},{"start":32.26,"end":33.02,"text":"So,","coverage":1},{"start":33.42,"end":34.34,"text":"to summarize,","coverage":1},{"start":35,"end":37.86,"text":"as well as habitat loss and human contact,","coverage":1},{"start":38.22,"end":41.28,"text":"the main threat to forest elephants comes from poaching.","coverage":1}],"file":"5abd7bd0102d2e07b5fe.js","track":0,"media":"../assets/media/5bf8f7a4809ea3e1fe318be3a7371f0006a4963ec39b28d06cc8481413f0e55c.mp3"}],"../assets/media/7e75148d824429ebf53940334cd91928b48dfcd1b2c8c05cef46fc67fe76ca47.mp3":[{"id":"PPT_7e75148d824429eb","audioId":"PPT_7e75148d824429eb","title":"Book 3 · Unit 1 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 79","duration":239.49,"cues":[{"start":0,"end":2.22,"text":"one .two","coverage":1},{"start":2.22,"end":2.78,"text":"Hello,","coverage":1},{"start":3.2,"end":4.72,"text":"and thank you all for coming.","coverage":1},{"start":5.28,"end":9.56,"text":"I know you're all busy students, and I appreciate that you're here today.","coverage":1},{"start":10.2,"end":15.02,"text":"As we all know, there are many animals which are disappearing from our planet.","coverage":1},{"start":16.22,"end":17.5,"text":"Rhinos, orangutans,","coverage":1},{"start":17.82,"end":18.86,"text":"sea turtles...","coverage":1},{"start":18.86,"end":20.38,"text":"the list is shocking.","coverage":1},{"start":21.38,"end":25.52,"text":"Now, what do you think of when you hear African elephant?","coverage":1},{"start":25.52,"end":28.04,"text":"Perhaps something like intelligent,","coverage":1},{"start":28.5,"end":29.06,"text":"majestic,","coverage":1},{"start":29.72,"end":30.14,"text":"powerful.","coverage":1},{"start":30.98,"end":35.34,"text":"Now, even though these words describe these creatures perfectly,","coverage":1},{"start":35.84,"end":39.48,"text":"those three qualities may not be enough to save them.","coverage":1},{"start":40.08,"end":45.2,"text":"A century ago, there were around five million elephants across Africa.","coverage":1},{"start":45.82,"end":50.36,"text":"Today, it is believed that there are less than 500 ,000.","coverage":1},{"start":50.36,"end":55.46,"text":"In fact, both species of African elephants are endangered.","coverage":1},{"start":56.26,"end":60.4,"text":"While people are generally more familiar with the savanna elephant,","coverage":1},{"start":60.92,"end":64.7,"text":"I'm here today to talk about the African forest elephant,","coverage":1},{"start":65.32,"end":66.26,"text":"which is smaller,","coverage":1},{"start":66.6,"end":67.64,"text":"less well known,","coverage":1},{"start":67.96,"end":72.72,"text":"and it's critically endangered because of the threat that it faces from humans.","coverage":1},{"start":73.8,"end":81.72,"text":"The main human threat to forest elephants comes from poachers, who hunt them for their long, white, beautiful tusks.","coverage":1},{"start":82.16,"end":85.32,"text":"It's widely known that these tusks are made of ivory,","coverage":1},{"start":85.8,"end":91.36,"text":"a material that poachers sell to make a lot of money, even though it's illegal.","coverage":1},{"start":92.32,"end":96.3,"text":"The international trade of ivory was banned in 1989,","coverage":1},{"start":96.74,"end":102.84,"text":"yet several countries still allow ivory to be bought and sold across their borders.","coverage":1},{"start":103.3,"end":106.76,"text":"This has actually increased over recent years.","coverage":1},{"start":106.76,"end":111.08,"text":"The second threat is the loss of the elephant's habitat,","coverage":1},{"start":111.5,"end":117.36,"text":"which happens when humans destroy rainforest areas to make the land suitable for farming.","coverage":1},{"start":118.36,"end":126.56,"text":"This means the elephants have less space to live in, so the food they depend on for survival, such as fruit, grasses,","coverage":1},{"start":126.88,"end":127.64,"text":"and leaves,","coverage":1},{"start":128.06,"end":130.22,"text":"not only becomes less available,","coverage":1},{"start":130.52,"end":134.62,"text":"but also has to be shared between the same number of elephants.","coverage":1},{"start":134.62,"end":139.74,"text":"A third threat is contact between humans and elephants.","coverage":1},{"start":140.44,"end":145.96,"text":"Habitat loss sometimes forces elephants to leave the rainforest and go into villages,","coverage":1},{"start":146.44,"end":149.52,"text":"where they damage crops growing in farmers' fields.","coverage":1},{"start":150.12,"end":151.04,"text":"Because of this,","coverage":1},{"start":151.64,"end":154.34,"text":"local people sometimes kill the elephants.","coverage":1},{"start":155,"end":158.74,"text":"They see this as the only way to protect themselves,","coverage":1},{"start":159.22,"end":162.52,"text":"their families, their food, and their homes.","coverage":1},{"start":163.54,"end":164.22,"text":"However,","coverage":1},{"start":164.7,"end":165.9,"text":"there is good news.","coverage":1},{"start":166.26,"end":170.14,"text":"It may not be too late to save the African forest elephant.","coverage":1},{"start":170.94,"end":174.86,"text":"But there are several things that really ought to happen first.","coverage":1},{"start":175.76,"end":176.3,"text":"First,","coverage":1},{"start":176.62,"end":184.94,"text":"there needs to be an increase in the number of specially trained guards who work in the rainforests to catch the poachers.","coverage":1},{"start":184.94,"end":186.16,"text":"Second,","coverage":1},{"start":187.18,"end":194.26,"text":"governments must introduce an immediate and complete ban on anyone buying or selling ivory,","coverage":1},{"start":194.82,"end":197.16,"text":"even between countries sharing a border.","coverage":1},{"start":198.5,"end":198.94,"text":"Third,","coverage":1},{"start":199.48,"end":204.22,"text":"we have to find ways of reducing contact between humans and elephants.","coverage":1},{"start":204.76,"end":205.5,"text":"For instance,","coverage":1},{"start":206.02,"end":211.84,"text":"local communities should be helped to build suitable fences that can protect their land.","coverage":1},{"start":212.98,"end":213.72,"text":"So,","coverage":1},{"start":214.1,"end":215.06,"text":"to summarize,","coverage":1},{"start":215.74,"end":218.56,"text":"as well as habitat loss and human contact,","coverage":1},{"start":218.92,"end":222,"text":"the main threat to forest elephants comes from poaching.","coverage":1},{"start":222.54,"end":225.3,"text":"We've got to end the illegal trade of ivory.","coverage":1},{"start":225.86,"end":232.34,"text":"The governments and environmental organizations who can do this must not delay for a moment longer.","coverage":1},{"start":232.68,"end":233.58,"text":"Without a ban,","coverage":1},{"start":234.1,"end":237.6,"text":"the African forest elephant may soon become extinct.","coverage":1}],"file":"7ee99b6771e3d09a8a17.js","track":0,"media":"../assets/media/7e75148d824429ebf53940334cd91928b48dfcd1b2c8c05cef46fc67fe76ca47.mp3"}],"../assets/media/84a3bb0e3d6ecb9691d9ee819f65cd49e6465baa55d41913fc0161f751bf018c.mp3":[{"id":"PPT_84a3bb0e3d6ecb96","audioId":"PPT_84a3bb0e3d6ecb96","title":"Book 3 · Unit 1 · LS · PREPARATION FOR SPEAKING","subtitle":"PREPARATION FOR SPEAKING · source slide 171","duration":83.51,"cues":[{"start":0,"end":1.44,"text":"one .seven","coverage":1},{"start":1.44,"end":6.08,"text":"It's often said that it's cruel to use animals for entertainment.","coverage":1},{"start":6.72,"end":9.7,"text":"However, I would like to argue against this idea.","coverage":1},{"start":10.54,"end":13.68,"text":"I know that many animal lovers would disagree with me,","coverage":1},{"start":13.98,"end":16.34,"text":"but let me explain my point of view.","coverage":1},{"start":17.32,"end":21.54,"text":"First of all, keeping animals in zoos helps protect them.","coverage":1},{"start":22,"end":22.92,"text":"For example,","coverage":1},{"start":23.3,"end":24.3,"text":"many species,","coverage":1},{"start":24.68,"end":27.58,"text":"such as the giant panda and the snow leopard,","coverage":1},{"start":28.12,"end":29.68,"text":"are endangered in the wild,","coverage":1},{"start":30.02,"end":32.58,"text":"so they are safer in zoos.","coverage":1},{"start":33.02,"end":37.18,"text":"Another point is that zoos have an important educational role.","coverage":1},{"start":37.8,"end":38.5,"text":"For instance,","coverage":1},{"start":38.84,"end":41.02,"text":"children can see animals up close.","coverage":1},{"start":41.6,"end":44.38,"text":"When I was a child, my father took me to the zoo.","coverage":1},{"start":44.92,"end":47.16,"text":"I learned about exotic animals,","coverage":1},{"start":47.52,"end":50.6,"text":"and I also learned to care about animals.","coverage":1},{"start":51.88,"end":54.28,"text":"Modern zoos have improved their conditions.","coverage":1},{"start":54.9,"end":55.54,"text":"Animals are","coverage":1},{"start":55.54,"end":55.72,"text":"no","coverage":1},{"start":55.72,"end":57.56,"text":"longer kept in small cages,","coverage":1},{"start":58.34,"end":63.38,"text":"and zoos have large areas where animals can feel as if they are in their natural habitat.","coverage":1},{"start":64.2,"end":65.34,"text":"To summarise,","coverage":1},{"start":65.7,"end":68.6,"text":"zoos help protect animals and educate us.","coverage":1},{"start":69.16,"end":69.74,"text":"In short,","coverage":1},{"start":70.56,"end":74.58,"text":"modern zoos are comfortable, safe places for wild animals.","coverage":1},{"start":74.58,"end":76.02,"text":"In conclusion,","coverage":1},{"start":76.82,"end":81.58,"text":"I believe that we should help zoos by visiting them and donating money.","coverage":1}],"file":"a5b7ee1b8445a5d21bc6.js","track":0,"media":"../assets/media/84a3bb0e3d6ecb9691d9ee819f65cd49e6465baa55d41913fc0161f751bf018c.mp3"}],"../assets/media/408cdfa1e67955fb9c42a6a12498e9497e5ba1a7ed59cc230bec379eef2def04.mp3":[{"id":"PPT_408cdfa1e67955fb","audioId":"PPT_408cdfa1e67955fb","title":"Book 3 · Unit 1 · LS · PREPARATION FOR SPEAKING","subtitle":"PREPARATION FOR SPEAKING · source slide 183","duration":37.85,"cues":[{"start":0,"end":1.32,"text":"one .eight.","coverage":1},{"start":1.88,"end":2.76,"text":"one.","coverage":1},{"start":3.88,"end":7.64,"text":"First of all, keeping animals in zoos helps protect them.","coverage":1},{"start":9.82,"end":10.7,"text":"two.","coverage":1},{"start":11.76,"end":12.58,"text":"For example,","coverage":1},{"start":13.1,"end":18.68,"text":"many species such as the giant panda and the snow leopard are endangered in the wild.","coverage":1},{"start":21.08,"end":21.96,"text":"three.","coverage":1},{"start":23.2,"end":27.42,"text":"Another point is that zoos have an important educational role.","coverage":1},{"start":29.56,"end":30.5,"text":"four.","coverage":1},{"start":32.08,"end":32.98,"text":"To summarise,","coverage":1},{"start":33.28,"end":36.04,"text":"zoos help protect animals and educate us.","coverage":1}],"file":"c2b2b9e89dfcbc798295.js","track":0,"media":"../assets/media/408cdfa1e67955fb9c42a6a12498e9497e5ba1a7ed59cc230bec379eef2def04.mp3"}],"../assets/media/2f21d8680df4c211b38c026d22076138246dfbdfcd0f421f4f2adb819fd5fce9.mp3":[{"id":"PPT_2f21d8680df4c211","audioId":"PPT_2f21d8680df4c211","title":"Book 3 · Unit 1 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 49","duration":297.04,"cues":[{"start":0,"end":1.38,"text":"Unit one,","coverage":1},{"start":2.18,"end":3.58,"text":"one .one","coverage":1},{"start":3.58,"end":4.16,"text":"Hello","coverage":1},{"start":4.16,"end":5.98,"text":"and welcome!","coverage":1},{"start":6.4,"end":9.72,"text":"Today's debate is on using animals for work.","coverage":1},{"start":10.36,"end":14.48,"text":"The first animal that was domesticated by humans is the dog.","coverage":1},{"start":14.9,"end":20.08,"text":"Even now, dogs are still used to protect our houses and keep us safe.","coverage":1},{"start":20.74,"end":25.14,"text":"Other domesticated animals used for food include sheep,","coverage":1},{"start":25.54,"end":26.84,"text":"cows, and goats.","coverage":1},{"start":26.84,"end":33.74,"text":"The first donkeys were used by humans approximately six ,000 years ago in Egypt.","coverage":1},{"start":34.28,"end":38.84,"text":"Horses were domesticated five ,000 years ago in Europe and Asia.","coverage":1},{"start":39.76,"end":44.12,"text":"All these animals have been used to help human beings survive,","coverage":1},{"start":44.64,"end":48.26,"text":"either by providing food or by working for us.","coverage":1},{"start":49.06,"end":50.6,"text":"Horses, camels,","coverage":1},{"start":50.98,"end":58.58,"text":"elephants – they have all helped humans explore their land and transport goods from one place to another.","coverage":1},{"start":59.18,"end":60.7,"text":"But is this fair?","coverage":1},{"start":61,"end":62.48,"text":"What about animal rights?","coverage":1},{"start":63.04,"end":66.52,"text":"To argue for this issue today, we have Amy Johnson,","coverage":1},{"start":67.08,"end":69.32,"text":"an animal rights activist and writer.","coverage":1},{"start":69.88,"end":72.52,"text":"To argue against the issue is Dr.","coverage":1},{"start":72.66,"end":73.58,"text":"Jacob Korean.","coverage":1},{"start":74.42,"end":74.88,"text":"Dr.","coverage":1},{"start":75.14,"end":77.7,"text":"Korean is a professor of zoology,","coverage":1},{"start":78.08,"end":84.28,"text":"which is the scientific study of animals, and a writer of several books on animal welfare.","coverage":1},{"start":84.9,"end":88.88,"text":"You both have two minutes to introduce your point of view.","coverage":1},{"start":89.52,"end":89.7,"text":"Ms.","coverage":1},{"start":89.9,"end":90.18,"text":"Johnson,","coverage":1},{"start":90.66,"end":91.78,"text":"would you like to begin?","coverage":1},{"start":92.52,"end":94.82,"text":"Thank you for inviting me to this debate.","coverage":1},{"start":95.6,"end":101.22,"text":"It's well known that animals have worked side by side with humans for thousands of years.","coverage":1},{"start":101.78,"end":106.7,"text":"In fact, they helped us develop our civilization and helped humans survive.","coverage":1},{"start":107.68,"end":112.44,"text":"Animals like elephants and horses were used to build amazing structures,","coverage":1},{"start":112.84,"end":114.14,"text":"like the pyramids in Egypt.","coverage":1},{"start":114.9,"end":119.9,"text":"Yet their hard work and suffering are hardly ever recognized.","coverage":1},{"start":120.94,"end":121.7,"text":"For example,","coverage":1},{"start":122.36,"end":127.72,"text":"horses, camels, and elephants were used to transport armies and soldiers during wars,","coverage":1},{"start":128.32,"end":131.02,"text":"and many of these animals died in these wars.","coverage":1},{"start":132.44,"end":133.9,"text":"And there are other examples.","coverage":1},{"start":134.54,"end":138.92,"text":"Even now, dogs are used to pull sleds in cold climates,","coverage":1},{"start":139.26,"end":141.04,"text":"and elephants are used for logging.","coverage":1},{"start":141.76,"end":146.28,"text":"These animals work long hours and live in difficult conditions.","coverage":1},{"start":147.36,"end":149.74,"text":"However, they get very little reward.","coverage":1},{"start":150.48,"end":152.92,"text":"Humans just use them to their advantage.","coverage":1},{"start":153.86,"end":157.12,"text":"My main argument is that in the modern world, there is","coverage":1},{"start":157.12,"end":157.42,"text":"no","coverage":1},{"start":157.42,"end":160.7,"text":"longer any need to use animals for work.","coverage":1},{"start":161.46,"end":163.92,"text":"We have technology that can replace them.","coverage":1},{"start":164.6,"end":168,"text":"It's similar to using children to work in factories.","coverage":1},{"start":168.92,"end":170.46,"text":"200 years ago,","coverage":1},{"start":170.94,"end":173.56,"text":"factory owners got rich by using children.","coverage":1},{"start":174.28,"end":178.84,"text":"Nowadays, people still get rich by using animals to do work for them.","coverage":1},{"start":179.74,"end":181.7,"text":"The problem is that the animals have","coverage":1},{"start":181.7,"end":181.98,"text":"no","coverage":1},{"start":181.98,"end":184.7,"text":"one to represent them and protect their rights.","coverage":1},{"start":185.5,"end":191.76,"text":"Even though animals work hard for us, they are often abandoned when they get sick or too old to work.","coverage":1},{"start":192.2,"end":193,"text":"They suffer.","coverage":1},{"start":193.68,"end":194.48,"text":"In short,","coverage":1},{"start":194.96,"end":201.4,"text":"I strongly believe that using animals for work is an old -fashioned and cruel practice.","coverage":1},{"start":202.58,"end":203.4,"text":"Thank you, Ms.","coverage":1},{"start":203.74,"end":203.96,"text":"Johnson.","coverage":1},{"start":204.66,"end":204.96,"text":"Dr.","coverage":1},{"start":205.24,"end":205.52,"text":"Kurian,","coverage":1},{"start":206.06,"end":207.62,"text":"your introduction, please.","coverage":1},{"start":208.32,"end":209.04,"text":"Thank you.","coverage":1},{"start":209.72,"end":213.76,"text":"It's true that animals have helped our civilization develop.","coverage":1},{"start":214.66,"end":218.86,"text":"Camels and horses helped us carry goods across huge distances.","coverage":1},{"start":219.5,"end":223.26,"text":"Dogs helped us hunt and protected us from wild animals.","coverage":1},{"start":224.16,"end":227.58,"text":"Humans don't have the skills or strength to do these jobs.","coverage":1},{"start":228.84,"end":231.92,"text":"I want to argue that in many low -income countries,","coverage":1},{"start":232.26,"end":234.16,"text":"people still need animals to survive.","coverage":1},{"start":234.94,"end":237.14,"text":"These are people who can't afford cars,","coverage":1},{"start":237.5,"end":239.76,"text":"house alarms or expensive machines.","coverage":1},{"start":240.86,"end":244.82,"text":"Another point is that not all animal use is abuse.","coverage":1},{"start":245.32,"end":246.34,"text":"On the contrary,","coverage":1},{"start":246.8,"end":247.56,"text":"without humans,","coverage":1},{"start":248.04,"end":251.3,"text":"these domesticated animals would not have been able to survive.","coverage":1},{"start":251.86,"end":253.66,"text":"They need us to take care of them.","coverage":1},{"start":254.68,"end":259.88,"text":"There are many animal lovers around the world who work in animal shelters and help animals.","coverage":1},{"start":260.54,"end":262.96,"text":"There are laws that stop animal suffering.","coverage":1},{"start":263.58,"end":269.88,"text":"And people give a lot of money to animal charities and organizations that help save wildlife.","coverage":1},{"start":270.82,"end":272.1,"text":"At the same time,","coverage":1},{"start":272.46,"end":277.1,"text":"there are still millions of children in the world who don't get this kind of treatment.","coverage":1},{"start":277.8,"end":279.82,"text":"They go without food or clothing.","coverage":1},{"start":280.78,"end":284.08,"text":"I strongly believe that in a modern society,","coverage":1},{"start":284.38,"end":289.34,"text":"people often care more about animals than they do about people in low -income countries.","coverage":1},{"start":290.38,"end":292.24,"text":"Thank you both for your arguments.","coverage":1},{"start":292.8,"end":295.04,"text":"Now let's hear from our listeners.","coverage":1}],"file":"cb86f0b0a696970a72b1.js","track":0,"media":"../assets/media/2f21d8680df4c211b38c026d22076138246dfbdfcd0f421f4f2adb819fd5fce9.mp3"}]};
window.SCHOOL_SOURCE_ANSWERS=[{"text":"1 Can animals solve problems? Give examples.Possible answer: Yes. Birds find food and mice find ways to escape danger.","slide":4,"shape":"16","bookPage":"16"},{"text":"2 How do animals play? Do you think they like puzzles or games? Why / Why not?Possible answer: Animals can learn through repetition and play. A pet may enjoy finding food hidden in a toy.","slide":4,"shape":"18","bookPage":"16"},{"text":"1 What is the goal of a game like a maze?Possible answer: The goal is to find a route to the exit or target.","slide":6,"shape":"29","bookPage":"16"},{"text":"2 In your opinion, is the chimpanzee thinking? Why / Why not?Possible answer: The chimpanzee seems to be looking carefully at the screen and choosing a direction.","slide":6,"shape":"30","bookPage":"16"},{"text":"3 Do you think the chimpanzee and the man are happy or angry?Possible answer: The man looks happy. The chimpanzee may look angry or excited.","slide":6,"shape":"31","bookPage":"16"},{"text":"1  A maze has paths that lead from an entrance to an exit.","slide":12,"shape":"8","bookPage":"16"},{"text":"2  Animals living in the wild are not kept in zoos.","slide":12,"shape":"9","bookPage":"16"},{"text":"3  Planning is a mental skill.","slide":12,"shape":"10","bookPage":"16"},{"text":"4  We can reflect upon an experience to understand it better.","slide":12,"shape":"11","bookPage":"16"},{"text":"1 The scientists wanted to find out if chimpanzees could …a look for food.b plan ahead.c protect themselves.Answer: b plan ahead.","slide":17,"shape":"16","bookPage":"17"},{"text":"2 The chimpanzee is able to …a use a computer.b ask for food.c listen to commands.Answer: a use a computer.","slide":18,"shape":"19","bookPage":"17"},{"text":"3 The goal of the game is to …a climb the stairs.b eat the cherries.c find the exit.Answer: c find the exit.","slide":19,"shape":"19","bookPage":"17"},{"text":"4 Sometimes Panzee is able to solve a maze more quickly than …a a human.b a computer.c the scientist.Answer: a a human.","slide":20,"shape":"19","bookPage":"17"},{"text":"5 According to the professor, chimpanzees are able to …a communicate.b make plans.c think faster than people.Answer: b make plans.","slide":21,"shape":"19","bookPage":"17"},{"text":"1 In the wild, chimpanzees have to look for friends. DNS.","slide":24,"shape":"18","bookPage":"17"},{"text":"2 Panzee can often complete mazes which she has never seen before. T.","slide":24,"shape":"20","bookPage":"17"},{"text":"3 Planning before acting is just a human skill. F. Planning before acting is not just a human skill.","slide":24,"shape":"22","bookPage":"17"},{"text":"4 The scientist says that chimpanzees reflect upon the past. T.","slide":24,"shape":"24","bookPage":"17"},{"text":"5 Chimpanzees can plan ahead for centuries. F. Chimpanzees can plan ahead over several days.","slide":25,"shape":"19","bookPage":"17"},{"text":"1 Make a list of five animals which are very intelligent.Possible examples: chimpanzees, parrots, dogs, gorillas and cats.","slide":27,"shape":"16","bookPage":"17"},{"text":"2 For each animal you chose, give an example of its intelligence.Possible answer: Chimpanzees solve mazes; parrots solve food puzzles; dogs learn commands; gorillas can learn signs; cats communicate with owners.","slide":27,"shape":"18","bookPage":"17"},{"text":"3 Do you think animals remember things? Give reasons and examples.Possible answer: Yes. A pet may remember its owner, and an animal may remember where it found food.","slide":28,"shape":"16","bookPage":"17"},{"text":"5  The use of animals in scientific experiments is a hugely important issue that everybody\nshould care about.","slide":39,"shape":"7","bookPage":"18"},{"text":"6  People must make big changes to the way they live to make sure animals can survive in\nthe future.","slide":39,"shape":"8","bookPage":"18"},{"text":"7  If zoo animals live in good conditions with plenty of space, scientists can learn a lot from\ntheir behaviour.","slide":39,"shape":"9","bookPage":"18"},{"text":"8  The abuse of circus animals should not be permitted.","slide":39,"shape":"10","bookPage":"18"},{"text":"Discuss: 1 Everybody should give more money to organizations that protect animals which are in danger.Possible answer: I agree because organizations need money to protect animals in danger.","slide":44,"shape":"16","bookPage":"18"},{"text":"Discuss: 2 People who let animals go hungry are cruel and should be punished for their actions.Possible answer: I agree that deliberately making animals go hungry is cruel.","slide":44,"shape":"17","bookPage":"18"},{"text":"Discuss: 3 Animals living in cages in zoos suffer for no good reason.Possible answer: I partly disagree. Some zoos provide good care, although poor conditions can cause suffering.","slide":44,"shape":"18","bookPage":"18"},{"text":"Discuss: 4 There are too many laws which defend the welfare of animals.Possible answer: I disagree. Laws are needed to protect animals that cannot defend themselves.","slide":45,"shape":"19","bookPage":"18"},{"text":"Discuss: 5 The use of animals in scientific experiments is a hugely important issue that everybody should care about.Possible answer: I agree that it is an important issue because both animal suffering and medical progress matter.","slide":45,"shape":"20","bookPage":"18"},{"text":"Discuss: 6 People must make big changes to the way they live to make sure animals can survive in the future.Possible answer: I agree. Protecting habitats may require people to change their behaviour.","slide":46,"shape":"19","bookPage":"18"},{"text":"Discuss: 7 If zoo animals live in good conditions with plenty of space, scientists can learn a lot from their behaviour.Possible answer: I agree that good conditions can help researchers observe animals, though the setting is different from the wild.","slide":46,"shape":"20","bookPage":"18"},{"text":"Discuss: 8 The abuse of circus animals should not be permitted.Possible answer: I agree that abuse should never be allowed.","slide":46,"shape":"21","bookPage":"18"},{"text":"1 How can using animals for work support human development?Possible answer: Animals have carried people and goods and helped people farm or build.","slide":48,"shape":"16","bookPage":"18"},{"text":"2 What is your opinion of buying and selling animals?Possible answer: People should adopt an animal when possible and make sure they can care for it.","slide":48,"shape":"18","bookPage":"18"},{"text":"Dogs: what work are they used for? protection and transport.","slide":50,"shape":"19","bookPage":"19"},{"text":"Horses: what work are they used for? building, transport and war.","slide":50,"shape":"21","bookPage":"19"},{"text":"Elephants: what work are they used for? building, transport and war.","slide":50,"shape":"23","bookPage":"19"},{"text":"Camels: what work are they used for? transport and war.","slide":50,"shape":"8","bookPage":"19"},{"text":"\nprotection\nbuilding\ntransport\nwar\ndogs\n✓\n\n✓\n\nhorses\n\n✓\n✓\n✓\nelephants\n\n✓\n✓\n✓\ncamels\n\n\n✓\n✓","slide":51,"shape":"15","bookPage":"19"},{"text":"(1) technology available today can replace work animals","slide":54,"shape":"20","bookPage":"19"},{"text":"(4) working animals necessary part of life for low-income people","slide":54,"shape":"21","bookPage":"19"},{"text":"(2) not enough people who represent animals or protect their rights","slide":54,"shape":"22","bookPage":"19"},{"text":"(5) use of animals for work not always abuse","slide":54,"shape":"23","bookPage":"19"},{"text":"(3) old-fashioned and cruel to use animals for work","slide":54,"shape":"24","bookPage":"19"},{"text":"(6) domesticated animals wouldn’t have been able to survive without humans","slide":54,"shape":"7","bookPage":"19"},{"text":"cons (Ms Johnson’s ideas)\npros (Dr Kuryan’s ideas)\nsuffering of working animals (e.g. horses, dogs, elephants) rarely recognized\nhumans lack skills and strength for some jobs\n(1) technology available today can replace work animals\n(4) working animals necessary part of life for low-income people\n(2) not enough people who represent animals or protect their rights\n(5) use of animals for work not always abuse\n(3) old-fashioned and cruel to use animals for work\n(6) domesticated animals wouldn’t have been able to survive without humans","slide":55,"shape":"14","bookPage":"19"},{"text":"11. What question is the history of working animals used to introduce?\nA. Which animal was the easiest to train.\nB. Whether making animals work is fair.\nC. How different animals carried heavy goods.","slide":58,"shape":"5","bookPage":null},{"text":"12. What is Johnson’s main complaint about the working arrangement?\nA. Animals receive care but have too little exercise.\nB. People give animals tasks that are too varied.\nC. People benefit while animals receive little in return.","slide":59,"shape":"5","bookPage":null},{"text":"1 The vets at the zoo are treating a critically ill tiger. Definition: in a way that is very bad or seriousCorrect.","slide":74,"shape":"18","bookPage":"25"},{"text":"2 There is concern that the giant panda will soon become extinct. Definition: at risk of no longer existingIncorrect. Extinct means a type of animal does not now exist.","slide":74,"shape":"19","bookPage":"25"},{"text":"3 Polar bears depend on sea ice for survival. Without it, it’s difficult for them to hunt seals. Definition: to needCorrect.","slide":74,"shape":"20","bookPage":"25"},{"text":"4 Most people have only seen lions in an animal park and not in their own habitat in Africa. Definition: a building where animals live in a zooIncorrect. A habitat is the natural environment of an animal or plant.","slide":75,"shape":"18","bookPage":"25"},{"text":"5 There are two species of elephants: Asian and African. Definition: a group of plants or animals which share similar featuresCorrect.","slide":75,"shape":"19","bookPage":"25"},{"text":"6 Gorillas are endangered. If we don’t do something to save them, they will probably disappear. Definition: dangerous to humansIncorrect. Endangered means at risk of no longer existing.","slide":75,"shape":"20","bookPage":"25"},{"text":"7 Because of what the poachers did to her mother, the baby orangutan was left alone in the forest. Definition: somebody who catches and kills animals even when it is against the lawCorrect.","slide":76,"shape":"18","bookPage":"25"},{"text":"8 The greatest human threat to the environment is climate change. Definition: the possibility of trouble, danger or disasterCorrect.","slide":76,"shape":"19","bookPage":"25"},{"text":"9 It is illegal to keep wild animals, like tigers, as pets. Definition: only possible if you have a licenceIncorrect. Illegal means not allowed by law.","slide":76,"shape":"20","bookPage":"25"},{"text":"1 Can you explain what is happening in the photos?Possible answer: An elephant is in a natural setting; a worker is caring for a young elephant; forest has been cleared for farming.","slide":80,"shape":"26","bookPage":"26"},{"text":"2 What threats do you think the speaker will talk about?Possible answer: hunting, habitat loss and contact with people.","slide":80,"shape":"27","bookPage":"26"},{"text":"3 Can you think of any other threats to African elephants?Possible answer: habitat loss and contact between humans and elephants.","slide":80,"shape":"28","bookPage":"26"},{"text":"4 Listen to the presentation. Were your ideas mentioned?The speaker discusses poachers, loss of habitat and contact between humans and elephants.","slide":82,"shape":"15","bookPage":"26"},{"text":"1  The elephant’s long, pointed teeth are its tusks.","slide":87,"shape":"8","bookPage":"26"},{"text":"2  A fence can stand around a field.","slide":87,"shape":"9","bookPage":"26"},{"text":"3  To ban an activity is to refuse to allow it by law.","slide":87,"shape":"10","bookPage":"26"},{"text":"1 Human threat: hunting by poachers.","slide":89,"shape":"17","bookPage":"26"},{"text":"2 Human threat: loss of habitat.","slide":89,"shape":"19","bookPage":"26"},{"text":"3 Human threat: contact between humans and elephants.","slide":89,"shape":"21","bookPage":"26"},{"text":"4 Help: increase the number of trained guards.","slide":89,"shape":"8","bookPage":"26"},{"text":"5 Help: ban buying and selling ivory.","slide":90,"shape":"18","bookPage":"26"},{"text":"6 Help: reduce contact between humans and elephants.","slide":90,"shape":"20","bookPage":"26"},{"text":"1 Today, the number of African elephants has probably fallen below 50,000. F. The recording says below 500,000.","slide":92,"shape":"20","bookPage":"26–27"},{"text":"2 A ban on the international trade of ivory was introduced in 1989. T.","slide":92,"shape":"21","bookPage":"26–27"},{"text":"3 Humans destroy forest areas where elephants live to create areas for farming. T.","slide":92,"shape":"22","bookPage":"26–27"},{"text":"4 Elephants are often killed because they damage the tracks people use to transport food. DNS.","slide":92,"shape":"23","bookPage":"26–27"},{"text":"5 It is the responsibility of police officers working in local towns to find poachers. F. Specially trained guards working in the rainforests catch poachers.","slide":93,"shape":"21","bookPage":"26–27"},{"text":"6 To keep elephants away, local communities should put up fences. T.","slide":93,"shape":"23","bookPage":"26–27"},{"text":"1 First, there needs to be an increase in the number of specially trained guards who work in the rainforests to catch the poachers.","slide":95,"shape":"14","bookPage":"27"},{"text":"2 Second, governments must introduce an immediate and complete ban on anyone buying or selling ivory.","slide":95,"shape":"16","bookPage":"27"},{"text":"3 So, to summarize, as well as habitat loss and human contact, the main threat to forest elephants comes from poaching.","slide":96,"shape":"17","bookPage":"27"},{"text":"1  large, white, strong  : NC (not complete).","slide":98,"shape":"7","bookPage":"28"},{"text":"2  pandas, sea turtles, chimpanzees, tigers  : C (complete).","slide":98,"shape":"8","bookPage":"28"},{"text":"3  poachers, loss of habitat, human contact  : C (complete).","slide":98,"shape":"9","bookPage":"28"},{"text":"4  more guards, a ban on selling ivory, building fences  : NC (not complete).","slide":98,"shape":"10","bookPage":"28"},{"text":"Use list 2 in a sentence with correct intonation.Pandas ↗, sea turtles ↗, chimpanzees ↗ and tigers ↘.","slide":102,"shape":"18","bookPage":"28"},{"text":"Use list 3 in a sentence with correct intonation.Threats include poachers ↗, loss of habitat ↗ and human contact ↘.","slide":102,"shape":"20","bookPage":"28"},{"text":"Use list 4 in a sentence with correct intonation.The talk suggests more guards ↗, a ban on selling ivory ↗ and building fences ↘.","slide":102,"shape":"22","bookPage":"28"},{"text":"abandonment: verb abandon; adjective abandoned.","slide":107,"shape":"16","bookPage":"22"},{"text":"abuse: noun abuse; adjective abused / abusive; adverb abusively.","slide":107,"shape":"18","bookPage":"22"},{"text":"analysis: verb analyze; adjective analytical; adverb analytically.","slide":107,"shape":"6","bookPage":"22"},{"text":"communication: verb communicate; adjective communicative; adverb communicatively.","slide":107,"shape":"20","bookPage":"22"},{"text":"connection: verb connect; adjective connected.","slide":108,"shape":"18","bookPage":"22"},{"text":"damage: verb damage; adjective damaged.","slide":108,"shape":"20","bookPage":"22"},{"text":"debate: verb debate; adjective debated / debatable.","slide":108,"shape":"6","bookPage":"22"},{"text":"environment: adjective environmental; adverb environmentally.","slide":108,"shape":"22","bookPage":"22"},{"text":"involvement: verb involve; adjective involved.","slide":109,"shape":"16","bookPage":"22"},{"text":"loss: verb lose; adjective lost.","slide":109,"shape":"18","bookPage":"22"},{"text":"protection: verb protect; adjective protected / protective; adverb protectively.","slide":109,"shape":"6","bookPage":"22"},{"text":"support / supporter: verb support; adjective supportive; adverb supportively.","slide":109,"shape":"20","bookPage":"22"},{"text":"survivor / survival: verb survive; adjective survivable / surviving.","slide":110,"shape":"17","bookPage":"22"},{"text":"noun\nverb\nadjective\nadverb\nabandonment\nabandon\nabandoned\n—\nabuse\nabuse\nabused / abusive\nabusively\nanalysis\nanalyze\nanalytical\nanalytically\ncommunication\ncommunicate\ncommunicative\ncommunicatively","slide":111,"shape":"15","bookPage":"22"},{"text":"noun\nverb\nadjective\nadverb\nconnection\nconnect\nconnected\n—\ndamage\ndamage\ndamaged\n—\ndebate\ndebate\ndebated / debatable\n—\nenvironment\n—\nenvironmental\nenvironmentally","slide":112,"shape":"16","bookPage":"22"},{"text":"noun\nverb\nadjective\nadverb\ninvolvement\ninvolve\ninvolved\n—\nloss\nlose\nlost\n—\nprotection\nprotect\nprotected / protective\nprotectively\nsupport / supporter\nsupport\nsupportive\nsupportively\nsurvivor / survival\nsurvive\nsurvivable / surviving\n—","slide":113,"shape":"15","bookPage":"22"},{"text":"1 The analysis of the blood sample showed that the horse was healthy.","slide":118,"shape":"14","bookPage":"23"},{"text":"2 Domesticated animals may find it very hard to survive in the wild.","slide":118,"shape":"16","bookPage":"23"},{"text":"3 Owners sometimes abandon their animals when they can no longer care for them.","slide":119,"shape":"14","bookPage":"23"},{"text":"4 She has always been very supportive of animal rights.","slide":119,"shape":"16","bookPage":"23"},{"text":"5 Using environmentally damaging chemicals on farms can endanger wild animals as well as plants.","slide":120,"shape":"17","bookPage":"23"},{"text":"6 Scientists are exploring how birds communicate with each other by using different sounds.","slide":120,"shape":"19","bookPage":"23"},{"text":"7 She has had a lot of involvement in animal rights for the last 25 years.","slide":120,"shape":"6","bookPage":"23"},{"text":"8 Many people are very protective towards animals and they want to care for them.","slide":120,"shape":"8","bookPage":"23"},{"text":"9 I listened to a debate about animal rights.","slide":121,"shape":"17","bookPage":"23"},{"text":"10 Many people who are abusive to animals aren’t that way on purpose.","slide":121,"shape":"19","bookPage":"23"},{"text":"1 You have to love animals to be a vet. O (obligation).","slide":128,"shape":"15","bookPage":"24"},{"text":"2 You mustn’t give human food to animals. P (prohibition).","slide":128,"shape":"16","bookPage":"24"},{"text":"3 If you want to work with animals, you could become a vet. A (advice).","slide":128,"shape":"17","bookPage":"24"},{"text":"4 We must do more as a society to prevent animal cruelty. O (obligation).","slide":128,"shape":"18","bookPage":"24"},{"text":"5 What courses do you need to complete to get a veterinary degree? O (obligation).","slide":128,"shape":"19","bookPage":"24"},{"text":"6 You ought to visit the San Diego Zoo. It has some great animals. A (advice).","slide":128,"shape":"20","bookPage":"24"},{"text":"7 We should be kind to animals. They have feelings, too. A (advice).","slide":128,"shape":"21","bookPage":"24"},{"text":"8 It might be a good idea to help out on a farm if you are interested in working with animals. A (advice).","slide":128,"shape":"22","bookPage":"24"},{"text":"1 a She has to wear a uniform to work.","slide":133,"shape":"14","bookPage":"24"},{"text":"2 a You mustn’t put your hand into the cage.","slide":133,"shape":"16","bookPage":"24"},{"text":"3 b I don’t need to go to work on Saturdays.","slide":134,"shape":"14","bookPage":"24"},{"text":"4 a You should call your grandparents to say “thank you”.","slide":134,"shape":"16","bookPage":"24"},{"text":"Give an obligation for a child visiting a zoo.Possible answer: You have to stay with your adult.","slide":140,"shape":"15","bookPage":"24"},{"text":"Give a second obligation.Possible answer: You have got to follow the rules.","slide":140,"shape":"17","bookPage":"24"},{"text":"Give a prohibition.Possible answer: You mustn’t touch the animals.","slide":140,"shape":"19","bookPage":"24"},{"text":"Give advice.Possible answer: You should bring water.","slide":141,"shape":"15","bookPage":"24"},{"text":"Give another piece of advice.Possible answer: You ought to speak quietly.","slide":141,"shape":"17","bookPage":"24"},{"text":"Give a possible activity.Possible answer: You might enjoy a keeper’s talk.","slide":141,"shape":"19","bookPage":"24"},{"text":"Give another possible activity.Possible answer: You could learn about an endangered animal.","slide":142,"shape":"16","bookPage":"24"},{"text":"The red panda is an endangered animal. It depends on forest habitat for food and shelter. People should protect its habitat.","slide":146,"shape":"6","bookPage":null},{"text":"You mustn't touch animals in their enclosures. You should read the safety signs. You could take notes about an animal you like.","slide":146,"shape":"9","bookPage":null},{"text":"11. How does the host explain animals’ contribution to human survival?\nA. They have mainly protected food from thieves.\nB. They have made exploration more important than farming.\nC. They have supplied food as well as labour.","slide":152,"shape":"5","bookPage":null},{"text":"12. What example does Johnson use to show that animals' contribution is often overlooked?\nA. Animals replaced all modern machines\nB. Animals helped build the pyramids\nC. Animals were kept only as pets","slide":153,"shape":"5","bookPage":null},{"text":"1. Johnson says working animals helped humans develop civilization.\nAnswer: TRUE","slide":156,"shape":"5","bookPage":null},{"text":"2. Using an elephant for logging costs ten thousand dollars a year.\nAnswer: NOT GIVEN","slide":156,"shape":"8","bookPage":null},{"text":"Elephants are entering fields at night. Local people could report where they see them. The community might build fences in the busiest places. This could reduce crop damage.","slide":161,"shape":"6","bookPage":null},{"text":"Poachers may sell ivory across borders. One government cannot solve this issue alone. Countries should cooperate and punish illegal trade. This may protect more elephants.","slide":161,"shape":"9","bookPage":null},{"text":"1 The introduction asks what a poacher is. Audience: B (secondary school students).","slide":166,"shape":"17","bookPage":"29"},{"text":"2 The introduction discusses research and technological innovations. Audience: C (scientists).","slide":166,"shape":"19","bookPage":"29"},{"text":"3 The introduction describes big creatures and asks their colour. Audience: A (young children).","slide":166,"shape":"6","bookPage":"29"},{"text":"1 Who is the audience? b university students.","slide":168,"shape":"18","bookPage":"30"},{"text":"2 What is the speaker’s purpose? a to inform the audience about human threats to the African forest elephant.","slide":168,"shape":"20","bookPage":"30"},{"text":"main idea\nAfrican forest elephants are threatened by humans.\nsupporting details\nThreats:\n• hunting by poachers\n• loss of forest habitat\n• contact between humans and elephants","slide":172,"shape":"13","bookPage":"30"},{"text":"supporting details\nWhat people should/must do to help:\n• increase the number of guards who catch poachers\n• introduce a total ban on buying and selling ivory\n• reduce contact between humans and elephants\nconclusion / summary\nPoaching, habitat loss and human contact threaten forest elephants. Governments and environmental organizations must act without delay.","slide":173,"shape":"13","bookPage":"30"},{"text":"main idea\nWhales are threatened by human activities.\nsupporting details\nThreats:\n• hunting\n• pollution in the ocean\n• fishing in whales’ habitat","slide":176,"shape":"17","bookPage":"31"},{"text":"supporting details\nWhat people should/must do to help:\n• stop hunting threatened whales\n• reduce plastic and other pollution\n• restrict harmful fishing in their habitat\nconclusion / summary\nHunting, pollution and fishing can threaten whale populations. People and governments must act to protect the chosen species.","slide":177,"shape":"15","bookPage":"31"},{"text":"What changes would you make for a professional conference?Possible answer: I would use more specialist language, explain the research in more detail and ask fewer basic questions.","slide":180,"shape":"13","bookPage":"31"},{"text":"1 What is the speaker’s opinion?The speaker supports zoos: he argues that they protect animals and educate people.","slide":182,"shape":"18","bookPage":"32"},{"text":"2 What points does the speaker make?Zoos protect animals, educate children and have improved their conditions.","slide":182,"shape":"20","bookPage":"32"},{"text":"3 What examples support the points?Giant pandas and snow leopards are endangered; the speaker learned at the zoo; modern zoos have larger habitat-like areas.","slide":183,"shape":"18","bookPage":"32"},{"text":"4 What advice does the speaker give?Visit zoos and donate money.","slide":183,"shape":"20","bookPage":"32"},{"text":"2  There are several issues with producing oil in the Arctic. First, it’s expensive. Furthermore, it’s bad for the environment.","slide":187,"shape":"6","bookPage":"32"},{"text":"1 Add an example: I think that zoos are sometimes good for animals.Possible answer: For example, they can help animals look after their babies and release them into the wild.","slide":189,"shape":"19","bookPage":"33"},{"text":"2 Add an example: You can see many exotic animals in zoos, …Possible answer: such as lions, tigers and elephants.","slide":189,"shape":"21","bookPage":"33"},{"text":"3 Add an example: Animals are sometimes unhappy in zoos.Possible answer: For instance, animals in cages that are too small may walk up and down repeatedly.","slide":190,"shape":"19","bookPage":"33"},{"text":"1  It’s often said that animals should not be used for entertainment.","slide":193,"shape":"6","bookPage":"33"},{"text":"2  It’s believed that people should spend more on protecting wildlife.","slide":193,"shape":"7","bookPage":"33"},{"text":"3  It’s widely known that animals need suitable habitats.","slide":193,"shape":"8","bookPage":"33"},{"text":"1 First of all, keeping animals in zoos helps protect them.","slide":195,"shape":"17","bookPage":"33"},{"text":"2 For example, many species, such as the giant panda and the snow leopard, are endangered in the wild.","slide":195,"shape":"18","bookPage":"33"},{"text":"3 Another point is that zoos have an important educational role.","slide":196,"shape":"17","bookPage":"33"},{"text":"4 To summarize, zoos help protect animals and educate us.","slide":196,"shape":"18","bookPage":"33"},{"text":"Use the signposting phrases to develop an idea about wildlife.Possible answer: It’s often said that we should do more to protect wildlife. First of all, animals need safe habitats. For example, forests provide food and shelter. Another point is that local people need support to protect the land. To summarize, protecting wildlife requires action from both communities and governments.","slide":200,"shape":"11","bookPage":"33"},{"text":"What do you think of when you hear “polar bear”? Perhaps you imagine a large, white, powerful animal. Today I’m going to talk about human threats to polar bears and what people can do to help.","slide":208,"shape":"13","bookPage":"34"},{"text":"First of all, it is widely known that polar bears depend on sea ice to hunt for food. When that habitat disappears, finding food becomes harder. Another point is that bears may spend more time near people. For example, a bear searching for food can enter a town, where both people and bears may be in danger.","slide":208,"shape":"14","bookPage":"34"},{"text":"However, there are things we can do. First, governments and communities should work to reduce dangerous contact between people and bears. They could use suitable warning systems and keep food waste secure. People mustn’t approach or feed wild bears.","slide":209,"shape":"14","bookPage":"34"},{"text":"Second, we need to reduce the activities that contribute to climate change. We should save energy and support efforts to protect the bears’ habitat. Even though one person cannot solve the whole problem, communities can work together.","slide":209,"shape":"15","bookPage":"34"},{"text":"To summarize, loss of habitat and contact with people are serious threats to polar bears. We must protect habitats and help people live safely alongside wildlife. Thank you for listening.","slide":210,"shape":"12","bookPage":"34"},{"text":"The talk introduces polar bears, explains threats, proposes actions and ends with\na summary.","slide":211,"shape":"8","bookPage":"34"},{"text":"First of all, Another point, For example, However, Second and To summarize guide\nthe audience.","slide":211,"shape":"11","bookPage":"34"},{"text":"Check your own threats, evidence, audience and conclusion. Time your talk and\npractise your list intonation.","slide":211,"shape":"14","bookPage":"34"},{"text":"First, sea turtles need quiet places to lay eggs. People must not walk on their nests. We could join a beach clean-up. To summarize, everyone can help protect turtles.","slide":215,"shape":"6","bookPage":null},{"text":"First, birds near our town lose nesting places when trees are cut down. This threatens their habitat. The community could plant native trees. To summarize, protecting trees can protect birds.","slide":216,"shape":"6","bookPage":null}];
